// Package configuration resolves configuration keys from a Source into a
// typed Config struct.
package configuration

import (
	"fmt"
	"strconv"
)

// Source resolves a configuration key to a raw value.
type Source func(key string) (value string, found bool)

// Config holds the parsed application configuration.
type Config struct {
	Port  int
	Name  string
	Debug bool
}

// Load reads configuration keys through source and returns a parsed Config.
// A key that is present but fails to parse is an error. Present-but-empty
// HELIOS_NAME is an error. Keys not present use defaults documented below.
//
// Keys and defaults:
//
//	HELIOS_PORT  Port  int     "8080"
//	HELIOS_NAME  Name  string  "helios"
//	HELIOS_DEBUG Debug bool    "false"
func Load(source Source) (Config, error) {
	var cfg Config

	// HELIOS_PORT
	portRaw := "8080"
	if v, ok := source("HELIOS_PORT"); ok {
		portRaw = v
	}
	port, err := strconv.Atoi(portRaw)
	if err != nil {
		return cfg, fmt.Errorf("HELIOS_PORT: %w", err)
	}
	if port < 1 || port > 65535 {
		return cfg, fmt.Errorf("HELIOS_PORT: value %d out of range [1, 65535]", port)
	}
	cfg.Port = port

	// HELIOS_NAME
	nameRaw := "helios"
	if v, ok := source("HELIOS_NAME"); ok {
		nameRaw = v
	}
	if nameRaw == "" {
		return cfg, fmt.Errorf("HELIOS_NAME: value must not be empty")
	}
	cfg.Name = nameRaw

	// HELIOS_DEBUG
	debugRaw := "false"
	if v, ok := source("HELIOS_DEBUG"); ok {
		debugRaw = v
	}
	debug, err := strconv.ParseBool(debugRaw)
	if err != nil {
		return cfg, fmt.Errorf("HELIOS_DEBUG: %w", err)
	}
	cfg.Debug = debug

	return cfg, nil
}

package main

import (
	"fmt"
	"os"

	"example.helios/configuration"
)

// envSource returns a Source that reads from the process environment.
func envSource(key string) (string, bool) {
	v, ok := os.LookupEnv(key)
	return v, ok
}

func main() {
	cfg, err := configuration.Load(envSource)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("port=%d name=%s debug=%t\n", cfg.Port, cfg.Name, cfg.Debug)
}

package configuration

import (
	"errors"
	"strconv"
	"testing"
)

func lookup(m map[string]string) Source {
	return func(key string) (string, bool) {
		v, ok := m[key]
		return v, ok
	}
}

func TestDefaults(t *testing.T) {
	cfg, err := Load(lookup(nil))
	if err != nil {
		t.Fatalf("Load with empty source: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want helios", cfg.Name)
	}
	if cfg.Debug {
		t.Errorf("Debug = %t, want false", cfg.Debug)
	}
}

func TestCustomValues(t *testing.T) {
	cfg, err := Load(lookup(map[string]string{
		"HELIOS_PORT":  "9090",
		"HELIOS_NAME":  "myapp",
		"HELIOS_DEBUG": "true",
	}))
	if err != nil {
		t.Fatalf("Load with custom values: %v", err)
	}
	if cfg.Port != 9090 {
		t.Errorf("Port = %d, want 9090", cfg.Port)
	}
	if cfg.Name != "myapp" {
		t.Errorf("Name = %q, want myapp", cfg.Name)
	}
	if !cfg.Debug {
		t.Errorf("Debug = %t, want true", cfg.Debug)
	}
}

func TestPortInvalidString(t *testing.T) {
	_, err := Load(lookup(map[string]string{
		"HELIOS_PORT": "not-a-number",
	}))
	if err == nil {
		t.Fatal("expected error for invalid port string")
	}
	if !errors.As(err, &strconv.NumError{}) {
		t.Errorf("expected *strconv.NumError in error chain, got %T", err)
	}
}

func TestPortOutOfRange(t *testing.T) {
	tests := []struct {
		val  string
		desc string
	}{
		{"0", "zero"},
		{"-1", "negative"},
		{"65536", "too large"},
		{"100000", "way too large"},
	}
	for _, tt := range tests {
		_, err := Load(lookup(map[string]string{"HELIOS_PORT": tt.val}))
		if err == nil {
			t.Errorf("expected error for port %s (%s)", tt.val, tt.desc)
		}
	}
}

func TestNameEmpty(t *testing.T) {
	tests := []struct {
		val  string
		desc string
	}{
		{"", "explicit empty"},
	}
	for _, tt := range tests {
		_, err := Load(lookup(map[string]string{"HELIOS_NAME": tt.val}))
		if err == nil {
			t.Errorf("expected error for HELIOS_NAME %q (%s)", tt.val, tt.desc)
		}
	}
}

func TestDebugInvalid(t *testing.T) {
	_, err := Load(lookup(map[string]string{
		"HELIOS_DEBUG": "not-a-bool",
	}))
	if err == nil {
		t.Fatal("expected error for invalid debug string")
	}
}

func TestDebugFalseVariants(t *testing.T) {
	for _, val := range []string{"false", "0", "FALSE", "f", "F"} {
		cfg, err := Load(lookup(map[string]string{"HELIOS_DEBUG": val}))
		if err != nil {
			t.Fatalf("Load with HELIOS_DEBUG=%q: %v", val, err)
		}
		if cfg.Debug {
			t.Errorf("Debug = true for HELIOS_DEBUG=%q", val)
		}
	}
}

func TestNameCustom(t *testing.T) {
	cfg, err := Load(lookup(map[string]string{
		"HELIOS_NAME": "production",
	}))
	if err != nil {
		t.Fatalf("Load with HELIOS_NAME=production: %v", err)
	}
	if cfg.Name != "production" {
		t.Errorf("Name = %q, want production", cfg.Name)
	}
}

func TestSourceNotFound(t *testing.T) {
	// Source returns found=false for everything.
	source := func(key string) (string, bool) {
		return "", false
	}
	cfg, err := Load(source)
	if err != nil {
		t.Fatalf("Load with all-not-found source: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want helios", cfg.Name)
	}
	if cfg.Debug {
		t.Errorf("Debug = %t, want false", cfg.Debug)
	}
}

func TestEmptyPortExplicit(t *testing.T) {
	// An empty string is not valid for Atoi.
	_, err := Load(lookup(map[string]string{
		"HELIOS_PORT": "",
	}))
	if err == nil {
		t.Fatal("expected error for empty HELIOS_PORT")
	}
}

